const r = await tools.exec_command({cmd:"python - <<'PY'
from pathlib import Path
import torch, torchvision.transforms as T
import torchvision.transforms.functional as TF
from torchvision import models
from PIL import Image
import timm, json, numpy as np, statistics, time
ROOT=Path('/workspace/IOAI/ioai2-competition-runs-task4-official-20260807T1230CST/ioai-2026-task-4-westlake-nlp-24/project/input/competition/data')
dev=torch.device('cuda:0' if torch.cuda.is_available() else 'cpu'); print('dev',dev)
r=models.resnet18(weights=None); r.load_state_dict(torch.load(ROOT/'models/resnet18.pth',map_location='cpu')); r.to(dev).eval()
v=timm.create_model('vit_tiny_patch16_224',pretrained=True,pretrained_cfg_overlay={'file':ROOT/'models/vit_tiny_patch16_224.safetensors','custom_load':False}).to(dev).eval()
for p in list(r.parameters())+list(v.parameters()): p.requires_grad_(False)
mean=torch.tensor([.485,.456,.406],device=dev).view(1,3,1,1); std=torch.tensor([.229,.224,.225],device=dev).view(1,3,1,1)
def prep(x,aa=None):
 x=TF.resize(x,256,interpolation=T.InterpolationMode.BILINEAR,antialias=aa) if aa is not None else TF.resize(x,256,interpolation=T.InterpolationMode.BILINEAR)
 x=TF.center_crop(x,224); return (x-mean)/std

def margin(z,y):
 t=z[:,y]; zz=z.clone(); zz[:,y]=-torch.inf; return (t-zz.max(1).values)
for split in ['train','test_public','test_leaderboard_a','test_leaderboard_b']:
 paths=sorted((ROOT/'dataset'/split/'images').glob('*.png')); labels=json.loads((ROOT/'dataset'/split/'labels.json').read_text()) if (ROOT/'dataset'/split/'labels.json').exists() else None
 records=[]; disagree=[]; aa_diff=[]
 t=time.time()
 for p in paths:
  x=TF.to_tensor(Image.open(p).convert('RGB')).to(dev)
  with torch.no_grad():
   z=prep(x); zr=r(z); zv=v(z); pr=int(zr.argmax(1)); pv=int(zv.argmax(1));
   mr=float(margin(zr, pr)); mv=float(margin(zv,pv));
   z2=prep(x,False); pr2=int(r(z2).argmax(1)); pv2=int(v(z2).argmax(1));
  y=int(labels[str(int(p.stem))]) if labels is not None else pr
  records.append((mr,mv,pr,pv,y, x.shape[-2],x.shape[-1]))
  if pr!=pv or (labels is not None and (pr!=y or pv!=y)): disagree.append((p.name,pr,pv,y,mr,mv))
  if (pr,pv)!=(pr2,pv2): aa_diff.append((p.name,(pr,pv),(pr2,pv2)))
 print('\n',split,'n',len(paths),'time',round(time.time()-t,2),'disagree',len(disagree),'aa_pred_diff',len(aa_diff))
 if disagree: print('dis first',disagree[:5])
 if aa_diff: print('aa diff first',aa_diff[:5])
 mrs=np.array([q[0] for q in records]); mvs=np.array([q[1] for q in records]);
 print('margin stats R median/p10/min',*[round(float(np.percentile(mrs,p)),3) for p in [50,10,1]],'V',*[round(float(np.percentile(mvs,p)),3) for p in [50,10,1]])
 print('smallest R',[(paths[i].name,round(float(mrs[i]),3),records[i][2:5]) for i in np.argsort(mrs)[:5]])
 print('smallest V',[(paths[i].name,round(float(mvs[i]),3),records[i][2:5]) for i in np.argsort(mvs)[:5]])
